CREATE OR REPLACE PROCEDURE sp(
    arg1 IN NUMBER, arg2 IN VARCHAR2, arg3 IN VARCHAR2,
    arg4 IN NUMBER, arg5 IN VARCHAR2, arg6 IN NUMBER
) AS
    v_threshold     NUMBER;
    v_status        VARCHAR2(4000);
    v_row_count     NUMBER;
    v_batch_size    NUMBER;
    v_selected_case NUMBER;
BEGIN
    v_threshold  := ROUND(arg1);
    v_status     := arg2;
    v_row_count  := 0;
    v_batch_size := 10;

    IF v_threshold < 3 THEN
        v_selected_case := 1;
        FOR rec IN (SELECT "ResID", "ResName", "Address", "Rating"
                      FROM "Restaurant"
                     WHERE "ResID" < arg1
                       AND "ResName" LIKE arg2)
        LOOP
            v_row_count := v_row_count + 1;

            IF rec."ResID" > 25 THEN
                UPDATE "Restaurant" SET "ResName" = 'PROMOTED'
                 WHERE "ResID" = rec."ResID";
            ELSIF rec."Address" = arg3 THEN
                DECLARE
                    v_visit_count NUMBER;
                BEGIN
                    SELECT COUNT(*) INTO v_visit_count
                      FROM "Visits_Restaurant" vr
                      JOIN "Student" s ON vr."StuID" = s."StuID"
                     WHERE vr."ResID" = rec."ResID"
                       AND s."LName" = arg5;

                    IF v_visit_count > 0 THEN
                        UPDATE "Restaurant" SET "Address" = 'RETAINED'
                         WHERE "ResID" = rec."ResID";
                    ELSE
                        DELETE FROM "Restaurant"
                         WHERE "ResID" = rec."ResID"
                           AND "ResName" = rec."ResName";
                        DELETE FROM "Visits_Restaurant"
                         WHERE "ResID" = rec."ResID";
                        DELETE FROM "Type_Of_Restaurant"
                         WHERE "ResID" = rec."ResID";
                    END IF;
                END;
            ELSE
                UPDATE "Restaurant" SET "Address" = 'PENDING'
                 WHERE "ResID" = rec."ResID";
                UPDATE "Restaurant" SET "Rating" = arg6
                 WHERE "ResID" = rec."ResID";
            END IF;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
                v_row_count  := 0;
            END IF;
        END LOOP;

    ELSIF v_threshold < 8 THEN
        v_selected_case := 2;
        FOR rec IN (SELECT "StuID", "LName"
                      FROM "Student"
                     WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15)
        LOOP
            v_row_count := v_row_count + 1;

            IF rec."LName" = arg5 THEN
                UPDATE "Student" SET "Major" = 700
                 WHERE "StuID" = rec."StuID";
            END IF;

            IF rec."LName" LIKE 'ACTIVE%' THEN
                UPDATE "Student" SET "LName" = 'PROCESSED'
                 WHERE "StuID" = rec."StuID";
            ELSIF rec."StuID" > arg4 + 5 THEN
                v_threshold := v_threshold + rec."StuID";
            ELSIF rec."LName" = 'EXPIRED' THEN
                DELETE FROM "Student" WHERE "StuID" = rec."StuID";
            END IF;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
                v_row_count  := 0;
            END IF;
        END LOOP;

    ELSIF v_threshold < 18 THEN
        v_selected_case := 3;
        FOR rec IN (SELECT "ResTypeID"
                      FROM "Restaurant_Type"
                     WHERE "ResTypeID" > arg6 - 20)
        LOOP
            v_row_count := v_row_count + 1;

            IF rec."ResTypeID" < 50 THEN
                v_status := 'LOW_PRIORITY';
            ELSIF rec."ResTypeID" < 150 THEN
                v_status := 'MEDIUM_PRIORITY';
            ELSE
                v_status := 'HIGH_PRIORITY';
            END IF;

            UPDATE "Restaurant_Type" SET "ResTypeID" = "ResTypeID" + 10
             WHERE "ResTypeID" = rec."ResTypeID";

            UPDATE "Type_Of_Restaurant" SET "ResTypeID" = "ResTypeID" + 10
             WHERE "ResTypeID" = rec."ResTypeID";

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
                v_row_count  := 0;
            END IF;
        END LOOP;

    ELSIF v_threshold < 25 THEN
        v_selected_case := 4;
        UPDATE "Restaurant" SET "Address" = 'ARCHIVED'
         WHERE "ResID" < arg1 AND "ResName" <> arg2;
        SELECT 1 INTO v_row_count FROM dual WHERE 1 = 0;

    ELSIF v_threshold < 40 THEN
        v_selected_case := 5;
        DELETE FROM "Student"
         WHERE "StuID" < arg4 AND "LName" = 'OBSOLETE';
        SELECT 1 INTO v_row_count FROM dual WHERE 1 = 0;

    ELSE
        v_selected_case := 6;
        UPDATE "Restaurant_Type" SET "ResTypeID" = arg6 + 100
         WHERE "ResTypeID" > 200;
        SELECT 1 INTO v_row_count FROM dual WHERE 1 = 0;
    END IF;

    -- Final checks (only reached for the first three cases)
    IF v_selected_case IN (1, 2, 3) THEN
        IF v_status = 'HIGH_PRIORITY' THEN
            UPDATE "Restaurant_Type" SET "ResTypeID" = "ResTypeID" * 2
             WHERE "ResTypeID" > 100;
        ELSIF v_selected_case = 5 THEN
            DELETE FROM "Restaurant"
             WHERE "Address" = 'ARCHIVED' AND "ResID" < v_threshold - 10;
        ELSIF v_row_count > 15 THEN
            UPDATE "Student" SET "LName" = 'BULK_PROCESSED'
             WHERE "StuID" BETWEEN arg4 AND arg4 + 50;
        ELSE
            UPDATE "Restaurant" SET "ResName" = arg3
             WHERE "ResID" > v_threshold;
        END IF;
    END IF;
END;
